-- Tag skinning ability spells with SpellFamily 14, mask 8 (Skinning)
-- Required for cast time reduction aura to affect skinning
UPDATE spell SET spell_class_set = 14, spell_class_mask_1 = 8 WHERE ID IN (8613, 8617, 8618, 10768, 32678, 50305) AND spell_class_set != 14;

-- Fix skinning ability cast time: index 10 (1.0s) → index 16 (1.5s) to match Wowhead/retail
-- The original DBC had 1.0s but Blizzard's spell_dbc override set 1.5s; we fix the DBC directly
UPDATE spell SET cast_time_index = 16 WHERE ID IN (8613, 8617, 8618, 10768, 32678, 50305) AND cast_time_index = 10;
